<template>
  <div class="quality-center page-container">
    <header class="page-heading"><div><span class="eyebrow">ANNOTATION QUALITY CENTER</span><h1>标注质量管理中心</h1><p>实现标注质量审核、一致性检查、标注员绩效评估、标注结果自动校验与纠偏，支持多轮标注与仲裁机制，建立标注质量评分体系，确保标注数据的高质量和高一致性。</p></div><div class="heading-actions"><el-button @click="router.push('/annotation-quality/rules')">规则配置后台</el-button><el-button type="primary" :disabled="!task" @click="publishTask">最终验收归档</el-button></div></header>
    <el-row :gutter="16" class="quality-layout">
      <el-col :xs="24" :lg="5"><el-card shadow="never" class="task-card"><template #header><div class="card-heading"><span>质检任务</span><el-button link :loading="loadingTasks" @click="loadTasks">刷新</el-button></div></template><el-input v-model="taskKeyword" clearable placeholder="搜索任务名称" class="task-search" /><el-select v-model="taskType" clearable placeholder="数据类型" style="width:100%" class="task-filter"><el-option label="文本" value="TEXT" /><el-option label="表格" value="TABLE" /><el-option label="图片" value="IMAGE" /><el-option label="视频" value="VIDEO" /></el-select><div class="task-list"><button v-for="item in filteredTasks" :key="item.id" :class="['task-item',{selected:item.id===task?.id}]" @click="selectTask(item)"><span class="task-status" :class="String(item.status || '').toLowerCase()" /><span><b>{{ item.name || `任务 ${item.id}` }}</b><small>{{ item.totalRows || 0 }} 条 · {{ item.status || '待质检' }}</small></span></button><el-empty v-if="!filteredTasks.length" description="暂无待质检任务" :image-size="70" /></div></el-card></el-col>
      <el-col :xs="24" :lg="19"><template v-if="task"><div class="flow-bar"><el-button :loading="actionLoading" @click="autoValidate">一键自动校验</el-button><el-button :loading="actionLoading" @click="runSampling">批量随机抽检</el-button><el-button :loading="actionLoading" @click="runConsistency">一致性批量比对</el-button><el-button :loading="actionLoading" @click="bulkReject">批量下发纠偏重标</el-button><el-button :loading="actionLoading" @click="openArbitration">争议集中仲裁</el-button><el-button type="success" :disabled="!qualityMetrics?.publishable" :loading="actionLoading" @click="publishTask">最终验收归档</el-button></div><el-tabs v-model="activeTab" class="quality-tabs"><el-tab-pane label="质量总览大盘" name="overview"><div class="metric-grid"><div v-for="metric in metricCards" :key="metric.label" class="metric-card"><span>{{ metric.label }}</span><strong>{{ metric.value }}</strong><small>{{ metric.note }}</small></div></div><el-row :gutter="16" class="overview-row"><el-col :xs="24" :lg="12"><el-card shadow="never"><template #header><span>质量异常分布</span></template><div class="bar-chart"><div v-for="item in issueBars" :key="item.label" class="bar-row"><span>{{ item.label }}</span><div><i :style="{width:`${item.value}%`}" :class="item.color" /></div><b>{{ item.value }}%</b></div><el-empty v-if="!issueBars.length" description="运行自动校验后生成异常分布" :image-size="70" /></div></el-card></el-col><el-col :xs="24" :lg="12"><el-card shadow="never"><template #header><span>质检完成趋势</span></template><div class="trend-placeholder"><strong>{{ completedCount }}</strong><span>当前已处理样本</span><el-progress :percentage="progress" :stroke-width="12" :status="progress === 100 ? 'success' : undefined" /><small>当前任务整体处理进度 {{ progress }}%</small></div></el-card></el-col></el-row><el-card shadow="never" class="issue-card"><template #header><div class="card-heading"><span>自动校验异常数据</span><el-button link type="primary" @click="activeTab='review'">进入审核工作台</el-button></div></template><el-table :data="reviewItems.slice(0,8)" stripe><el-table-column prop="rowIndex" label="样本行" width="100" /><el-table-column prop="labelName" label="当前标签" /><el-table-column prop="status" label="状态"><template #default="s"><el-tag :type="statusType(s.row.status)">{{ statusText(s.row.status) }}</el-tag></template></el-table-column><el-table-column prop="reviewComment" label="异常/审核说明" show-overflow-tooltip /><el-table-column label="处理" width="110"><template #default="s"><el-button link type="primary" @click="openReview(s.row)">处理</el-button></template></el-table-column></el-table><el-empty v-if="!reviewItems.length" description="当前没有异常样本" :image-size="70" /></el-card></el-tab-pane>
        <el-tab-pane label="人工质量审核工作台" name="review"><div class="review-toolbar"><el-checkbox v-model="selectAll">全选待审核样本</el-checkbox><span>已选 {{ selectedIds.length }} 条</span><el-button size="small" type="success" :disabled="!selectedIds.length" @click="bulkReview(true)">批量通过</el-button><el-button size="small" type="warning" :disabled="!selectedIds.length" @click="bulkReject">批量驳回重标</el-button></div><el-row :gutter="16"><el-col :xs="24" :lg="9"><el-card shadow="never" class="sample-list"><button v-for="item in reviewItems" :key="item.id" :class="['sample-item',{selected:item.id===reviewing?.id}]" @click="openReview(item)"><el-checkbox :model-value="selectedIds.includes(item.id)" @click.stop="toggleSelected(item.id)" /><span><b>样本 {{ item.rowIndex + 1 }}</b><small>{{ item.labelName || item.labelCode || '未标注' }} · {{ statusText(item.status) }}</small></span></button><el-empty v-if="!reviewItems.length" description="暂无待审核样本" :image-size="80" /></el-card></el-col><el-col :xs="24" :lg="15"><el-card shadow="never" class="review-editor"><template #header><div class="card-heading"><span>审核详情</span><el-tag v-if="reviewing" :type="statusType(reviewing.status)">{{ statusText(reviewing.status) }}</el-tag></div></template><template v-if="reviewing"><div class="source-block"><span>原始样本</span><div v-for="(value,key) in sourceRow" :key="key"><small>{{ key }}</small><p>{{ value ?? '（空）' }}</p></div></div><el-form label-position="top"><el-form-item label="修正标签"><el-select v-model="reviewDraft.labelCode" style="width:100%"><el-option v-for="label in labels" :key="label.code" :label="label.name" :value="label.code" /></el-select></el-form-item><el-form-item label="审核意见"><el-input v-model="reviewDraft.comment" type="textarea" :rows="4" placeholder="通过可填写说明；驳回必须填写原因" /></el-form-item></el-form><div class="review-actions"><el-button type="success" @click="reviewOne(true)">审核通过</el-button><el-button type="warning" @click="reviewOne(false)">驳回并下发重标</el-button><el-button type="danger" @click="arbitrateOne">标记争议</el-button></div></template><el-empty v-else description="请选择待审核样本" :image-size="100" /></el-card></el-col></el-row></el-tab-pane>
        <el-tab-pane label="一致性校验 / 多轮 / 仲裁" name="consistency"><el-card shadow="never" class="consistency-card"><template #header><div class="card-heading"><span>多人 / 多轮标注结果对比</span><el-button type="primary" :loading="actionLoading" @click="runConsistency">执行一致性检查</el-button></div></template><el-alert v-if="consistencyReport" :title="consistencyReport.recommendation || '一致性检查已完成'" :type="consistencyReport.inconsistentCount ? 'warning' : 'success'" show-icon :closable="false" /><div class="comparison-grid"><div><span class="section-label">一致性得分</span><strong>{{ qualityMetrics ? percent(qualityMetrics.consistencyRate) : '-' }}</strong><small>低于规则阈值的样本将进入仲裁池</small></div><div><span class="section-label">当前轮次</span><strong>{{ task.round || 1 }} 轮</strong><small>支持查看标注纠偏后的最终版本</small></div><div><span class="section-label">争议样本</span><strong>{{ arbitrationItems.length }}</strong><small>待管理员裁定并留存操作日志</small></div></div><el-divider content-position="left">分歧与仲裁池</el-divider><el-table :data="arbitrationItems" stripe><el-table-column prop="rowIndex" label="样本行" width="100" /><el-table-column prop="labelCode" label="当前结果" /><el-table-column prop="originalLabelCode" label="上一轮结果" /><el-table-column prop="reviewComment" label="争议说明" show-overflow-tooltip /><el-table-column label="操作" width="120"><template #default="s"><el-button link type="danger" @click="openReview(s.row); activeTab='review'">进入仲裁</el-button></template></el-table-column></el-table><el-empty v-if="!arbitrationItems.length" description="暂无待仲裁样本" :image-size="70" /></el-card></el-tab-pane>
        <el-tab-pane label="标注员绩效评估" name="performance"><el-card shadow="never"><template #header><div class="card-heading"><span>标注员绩效排行榜</span><div><el-button link @click="loadPerformance">刷新</el-button><el-button type="primary" plain @click="exportPerformance">导出 Excel</el-button></div></div></template><el-table :data="performance" stripe><el-table-column type="index" label="排名" width="70" /><el-table-column prop="annotatorId" label="标注员" /><el-table-column prop="total" label="有效标注量" /><el-table-column prop="approved" label="合格量" /><el-table-column prop="rejected" label="驳回次数" /><el-table-column label="一致性平均分"><template #default="s">{{ percent(s.row.consistencyRate || s.row.approvalRate) }}</template></el-table-column><el-table-column label="综合质量得分"><template #default="s"><el-tag :type="s.row.performanceScore >= .8 ? 'success' : 'warning'">{{ percent(s.row.performanceScore) }}</el-tag></template></el-table-column><el-table-column label="详情" width="90"><template #default="s"><el-button link type="primary" @click="showPerformance(s.row)">查看</el-button></template></el-table-column></el-table><el-empty v-if="!performance.length" description="暂无绩效数据" :image-size="70" /></el-card></el-tab-pane></el-tabs></template><el-empty v-else description="请从左侧选择待质检任务" :image-size="120" /></el-col>
    </el-row>
    <el-dialog v-model="performanceDialog" title="标注员绩效详情" width="560px"><template v-if="selectedPerformance"><el-descriptions :column="2" border><el-descriptions-item label="标注员">{{ selectedPerformance.annotatorId }}</el-descriptions-item><el-descriptions-item label="有效标注">{{ selectedPerformance.total || 0 }}</el-descriptions-item><el-descriptions-item label="通过率">{{ percent(selectedPerformance.approvalRate) }}</el-descriptions-item><el-descriptions-item label="纠偏率">{{ percent(selectedPerformance.correctionRate) }}</el-descriptions-item><el-descriptions-item label="综合得分">{{ percent(selectedPerformance.performanceScore) }}</el-descriptions-item></el-descriptions><el-alert class="dialog-tip" title="详细工作量趋势与错误类型统计将在后端绩效明细接口启用后展示，当前指标来自任务级绩效统计。" type="info" :closable="false" /></template></el-dialog>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import request from '../utils/request'
import { getActiveDatasetId } from '../utils/workspaceSync'
const router = useRouter(); const route = useRoute(); const tasks = ref([]); const task = ref(null); const annotations = ref([]); const labels = ref([]); const qualityMetrics = ref(null); const performance = ref([]); const consistencyReport = ref(null); const samplingReport = ref(null); const loadingTasks = ref(false); const actionLoading = ref(false); const activeTab = ref('overview'); const taskKeyword = ref(''); const taskType = ref(''); const reviewing = ref(null); const selectedIds = ref([]); const selectAll = ref(false); const performanceDialog = ref(false); const selectedPerformance = ref(null); const previewRows = ref([]); const reviewDraft = reactive({ labelCode: '', comment: '' })
const percent = value => value == null ? '-' : `${(Number(value) * 100).toFixed(1)}%`; const filteredTasks = computed(() => tasks.value.filter(item => (!taskKeyword.value || String(item.name || '').toLowerCase().includes(taskKeyword.value.toLowerCase())) && (!taskType.value || String(item.annotationType || item.dataType || '').toUpperCase() === taskType.value))); const reviewItems = computed(() => annotations.value.filter(x => ['SUBMITTED','IN_REVIEW','REJECTED','PRE_ANNOTATED'].includes(x.status))); const arbitrationItems = computed(() => annotations.value.filter(x => ['IN_REVIEW','REJECTED'].includes(x.status))); const completedCount = computed(() => annotations.value.filter(x => ['SUBMITTED','IN_REVIEW','APPROVED','ARBITRATED','PUBLISHED'].includes(x.status)).length); const progress = computed(() => annotations.value.length ? Math.round(completedCount.value / annotations.value.length * 100) : 0); const sourceRow = computed(() => currentRow.value || {}); const currentRow = ref(null); const metricCards = computed(() => [{ label:'任务综合质量总分', value:percent(qualityMetrics.value?.qualityScore), note:'加权评分结果' },{ label:'人工审核通过率', value:percent(qualityMetrics.value?.approveRate), note:'审核通过 / 已审核' },{ label:'多人标注一致性率', value:percent(qualityMetrics.value?.consistencyRate), note:'一致性检查结果' },{ label:'自动校验合格率', value:percent(qualityMetrics.value?.validationRate ?? qualityMetrics.value?.approveRate), note:'规则校验通过' },{ label:'标注纠偏修正率', value:percent(qualityMetrics.value?.correctionRate), note:'发生纠偏的样本' },{ label:'争议仲裁发生率', value:percent(qualityMetrics.value?.arbitrationRate), note:'进入仲裁池比例' },{ label:'待审核未处理', value:qualityMetrics.value?.pendingReviewCount ?? reviewItems.value.length, note:'需要人工处理' }]); const issueBars = computed(() => { const groups = {}; reviewItems.value.forEach(x => { const key = x.status === 'REJECTED' ? '驳回重标' : x.status === 'IN_REVIEW' ? '争议复核' : '待校验'; groups[key] = (groups[key] || 0) + 1 }); const total = Math.max(reviewItems.value.length, 1); return Object.entries(groups).map(([label,count],index) => ({ label, value:Math.round(count / total * 100), color:['blue','orange','red'][index % 3] })) })
const statusText = s => ({ PRE_ANNOTATED:'预标注', SUBMITTED:'待审核', IN_REVIEW:'争议复核', REJECTED:'待重标', APPROVED:'已通过', ARBITRATED:'已仲裁', PUBLISHED:'已归档' }[s] || s || '待处理'); const statusType = s => ['APPROVED','PUBLISHED'].includes(s) ? 'success' : ['IN_REVIEW','SUBMITTED','ARBITRATED'].includes(s) ? 'warning' : s === 'REJECTED' ? 'danger' : 'info'
const loadTasks = async () => { loadingTasks.value = true; try { const result = await request.get('/v1/annotation-tasks?page=1&size=100'); tasks.value = (result.records || []).filter(x => x.status !== 'CANCELLED'); const activeId = getActiveDatasetId(); const scoped = activeId ? tasks.value.filter(x => String(x.datasetId) === String(activeId)) : []; const pool = scoped.length ? scoped : tasks.value; const queryTask = Number(route.query.taskId); const selected = tasks.value.find(x => x.id === queryTask) || pool[0]; if (selected) await selectTask(selected) } catch (e) { ElMessage.error(e.message || '质量任务加载失败') } finally { loadingTasks.value = false } }
const selectTask = async item => { task.value = item; activeTab.value = 'overview'; try { annotations.value = await request.get(`/v1/annotation-tasks/${item.id}/annotations`) || []; qualityMetrics.value = await request.get(`/v1/annotation-tasks/${item.id}/quality-metrics`); labels.value = item.labelSchemaId ? await request.get(`/v1/label-schemas/${item.labelSchemaId}/children`) : []; performance.value = await request.get(`/v1/annotation-tasks/${item.id}/annotator-performance`) || []; const dataset = await request.get(`/v1/datasets/${item.datasetId}/preview`).catch(() => []); previewRows.value = Array.isArray(dataset) ? dataset : dataset?.rows || []; currentRow.value = previewRows.value[annotations.value[0]?.rowIndex || 0] || null } catch (e) { ElMessage.error(e.message || '质量数据加载失败') } }
const refresh = async () => { if (task.value) await selectTask(task.value) }; const autoValidate = async () => { actionLoading.value = true; try { const result = await request.post(`/v1/annotation-tasks/${task.value.id}/auto-validate`); ElMessage.success(`自动校验完成，${result?.routedToReview || 0} 条进入复核`); await refresh() } catch(e) { ElMessage.error(e.message) } finally { actionLoading.value = false } }; const runSampling = async () => { actionLoading.value = true; try { const result = await request.post(`/v1/annotation-tasks/${task.value.id}/quality-sampling`, { sampleRate: .1 }); activeTab.value = 'review'; const pending = result?.pendingReviewCount || 0; ElMessage.success(pending ? `抽检完成，${pending} 条已进入人工审核` : '抽检人工结论已保存'); await refresh() } catch(e) { ElMessage.error(e.message) } finally { actionLoading.value = false } }; const runConsistency = async () => { actionLoading.value = true; try { consistencyReport.value = await request.post(`/v1/annotation-tasks/${task.value.id}/consistency-check`); activeTab.value = 'consistency'; await refresh(); ElMessage.success('一致性检查已完成') } catch(e) { ElMessage.error(e.message) } finally { actionLoading.value = false } }
const openReview = item => { reviewing.value = item; activeTab.value = 'review'; reviewDraft.labelCode = item.labelCode || ''; reviewDraft.comment = item.reviewComment || item.comment || ''; currentRow.value = previewRows.value[item.rowIndex] || currentRow.value || {} }; const toggleSelected = id => { selectedIds.value = selectedIds.value.includes(id) ? selectedIds.value.filter(x => x !== id) : [...selectedIds.value, id] }; watch(selectAll, value => { if (value) selectedIds.value = reviewItems.value.map(x => x.id); else if (selectedIds.value.length === reviewItems.value.length) selectedIds.value = [] }); const reviewOne = async approved => { if (!reviewing.value) return; if (!approved && !reviewDraft.comment.trim()) return ElMessage.warning('驳回必须填写原因'); actionLoading.value = true; try { await request.post(`/v1/annotations/${reviewing.value.id}/review`, { approved, reviewComment: reviewDraft.comment }); ElMessage.success(approved ? '审核通过' : '已下发重标'); await refresh() } catch(e) { ElMessage.error(e.message) } finally { actionLoading.value = false } }; const bulkReview = async approved => { if (!selectedIds.value.length) return; actionLoading.value = true; try { for (const id of selectedIds.value) await request.post(`/v1/annotations/${id}/review`, { approved, reviewComment: approved ? '批量审核通过' : '批量纠偏重标' }); selectedIds.value = []; selectAll.value = false; ElMessage.success('批量审核完成'); await refresh() } catch(e) { ElMessage.error(e.message) } finally { actionLoading.value = false } }; const bulkReject = async () => { if (!selectedIds.value.length) selectedIds.value = reviewItems.value.map(x => x.id); await bulkReview(false) }; const arbitrateOne = async () => { if (!reviewing.value || !labels.value.length) return ElMessage.warning('当前任务没有可用标签'); const label = labels.value.find(x => x.code === reviewDraft.labelCode) || labels.value[0]; await request.post(`/v1/annotations/${reviewing.value.id}/arbitrate`, { labelCode: label.code, labelName: label.name, comment: reviewDraft.comment || '管理员仲裁确认' }); ElMessage.success('已完成仲裁并纠偏'); await refresh() }; const openArbitration = () => { activeTab.value = 'consistency'; if (arbitrationItems.value.length) openReview(arbitrationItems.value[0]) }; const publishTask = async () => { if (!task.value) return; try { await ElMessageBox.confirm('确认质量达标并归档当前任务？', '最终验收归档', { type:'warning' }); actionLoading.value = true; await request.post(`/v1/annotation-tasks/${task.value.id}/publish`); ElMessage.success('任务已验收归档'); await refresh() } catch(e) { if (e !== 'cancel') ElMessage.error(e.message) } finally { actionLoading.value = false } }; const loadPerformance = async () => { if (task.value) performance.value = await request.get(`/v1/annotation-tasks/${task.value.id}/annotator-performance`) || [] }; const showPerformance = row => { selectedPerformance.value = row; performanceDialog.value = true }; const exportPerformance = () => { const header = '标注员,有效标注量,合格量,驳回次数,通过率,综合质量得分'; const body = performance.value.map(x => [x.annotatorId,x.total || 0,x.approved || 0,x.rejected || 0,percent(x.approvalRate),percent(x.performanceScore)].join(',')).join('\n'); const blob = new Blob([`${header}\n${body}`], { type:'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `${task.value?.name || '标注员绩效'}-performance.csv`; link.click(); URL.revokeObjectURL(url) }
watch(() => reviewing.value?.id, id => { const item = annotations.value.find(x => x.id === id); if (item) currentRow.value = currentRow.value || {} }); onMounted(loadTasks)
</script>

